1	/**
2	 * update-plan.ts — what taking a newer release onto this tree means, path by path.
3	 *
4	 * # The idea, and why nothing else had to be invented
5	 *
6	 * `.github/atomaton-release.json` records the release this tree came from. That
7	 * fact is all a mechanical update needs, because it makes the ordinary git
8	 * three-way merge available:
9	 *
10	 *     base    = the release the tree came from (its asset's files)
11	 *     ours    = the adopter's tree, as it stands
12	 *     theirs  = the release being taken (its asset's files)
13	 *
14	 * Everything an upgrade policy would otherwise hand-write falls out of the
15	 * comparison. A file the adopter never touched takes the new version silently. A
16	 * file the adopter changed and upstream did not keeps the adopter's words. A file
17	 * both sides changed needs a look — and that is the whole, exact definition of
18	 * "this update needs a person": not an upstream declaration about some average
19	 * adopter, but the collision this particular tree actually has. Upstream cannot
20	 * know whether an adopter customised `config.yaml`; only the tree can answer, and
21	 * only at update time.
22	 *
23	 * # What this module decides, and what it refuses to decide
24	 *
25	 * This is the classification layer: which paths changed upstream, which the
26	 * adopter touched, and which strategy each one takes. It does not perform merges
27	 * — "merge" entries are paths where the outcome is only knowable by running the
28	 * merge (`git merge-file`, in the machinery that applies this plan). It also never
29	 * proposes touching a path that is in neither release: the adopter's own files are
30	 * outside this computation entirely, which is why the plan needs no ownership
31	 * table and no namespace rules. A layout change upstream needs no change here.
32	 *
33	 * Pure: three content maps in, one plan out.
34	 */
35	import { noLongerShipped, type ReleaseManifest } from "./release-manifest.ts";
36	
37	/** What upstream did to a path, read from the two releases' contents. */
38	export type UpstreamChange = "added" | "deleted" | "modified" | "unchanged";
39	
40	/** What the plan proposes for a path. */
41	export type UpdateOutcome =
42	  /** Upstream changed it, the adopter did not: the new content goes in. */
43	  | "take"
44	  /** Upstream added it, nothing of the adopter's is in the way. */
45	  | "add"
46	  /** Upstream removed it, the adopter's copy still matches: removed here too. */
47	  | "delete"
48	  /** Both sides changed it: the merge run decides merged or conflicted. */
49	  | "merge"
50	  /** The adopter's words win, and a person should see why. */
51	  | "keep"
52	  /** Nothing to do. */
53	  | "skip";
54	
55	export interface PlanEntry {
56	  readonly path: string;
57	  readonly upstream: UpstreamChange;
58	  /** Whether the adopter's copy differs from the base release's. */
59	  readonly oursModified: boolean;
60	  readonly outcome: UpdateOutcome;
61	}
62	
63	export interface UpdatePlan {
64	  /** The release the tree came from, as the tag names it. */
65	  readonly base: string;
66	  /** The release being taken, as the tag names it. */
67	  readonly target: string;
68	  /** Every path in either release's file list, sorted. */
69	  readonly entries: readonly PlanEntry[];
70	  readonly take: readonly string[];
71	  readonly add: readonly string[];
72	  readonly delete: readonly string[];
73	  /** Paths where both sides changed: the merge run answers merged or conflicted. */
74	  readonly merge: readonly string[];
75	  /**
76	   * The `keep` entries, in the order a person meets them: an upstream addition
77	   * landing where the adopter's own file already stands, an upstream deletion the
78	   * adopter had edited, an upstream modification of a file the adopter deleted.
79	   */
80	  readonly kept: readonly PlanEntry[];
81	}
82	
83	/**
84	 * The plan for moving a tree from its release to another one.
85	 *
86	 * `ours` answers "what does the adopter's tree hold at this path" for the paths
87	 * in either release — `undefined` is a path the tree does not have. Paths in
88	 * neither release are invisible here by construction; they are the adopter's.
89	 */
90	export function planUpdate(
91	  base: string,
92	  target: string,
93	  baseFiles: ReadonlyMap<string, string>,
94	  targetFiles: ReadonlyMap<string, string>,
95	  ours: ReadonlyMap<string, string>,
96	): UpdatePlan {
97	  const paths = new Set([...baseFiles.keys(), ...targetFiles.keys()]);
98	  const entries: PlanEntry[] = [];
99	
100	  for (const path of [...paths].sort()) {
101	    const baseContent = baseFiles.get(path);
102	    const targetContent = targetFiles.get(path);
103	    const oursContent = ours.get(path);
104	
105	    let upstream: UpstreamChange;
106	    if (baseContent === undefined && targetContent !== undefined) upstream = "added";
107	    else if (baseContent !== undefined && targetContent === undefined) upstream = "deleted";
108	    else if (baseContent === targetContent) upstream = "unchanged";
109	    else upstream = "modified";
110	
111	    // Whether something of the adopter's sits on this path that the base release
112	    // did not put there: an edit they made, or (for a path upstream adds) a file
113	    // of their own that was never part of any release.
114	    const inTheWay = oursContent !== undefined && oursContent !== baseContent;
115	
116	    let outcome: UpdateOutcome;
117	    if (upstream === "added") {
118	      outcome = inTheWay ? "keep" : "add";
119	    } else if (upstream === "deleted") {
120	      outcome = oursContent === undefined ? "skip" : inTheWay ? "keep" : "delete";
121	    } else if (upstream === "unchanged") {
122	      outcome = "skip";
123	    } else {
124	      // modified. An adopter who deleted the path keeps it deleted -- upstream's
125	      // fix is not forced back onto a tree that chose to live without it.
126	      if (oursContent === undefined) outcome = "keep";
127	      else if (!inTheWay) outcome = "take";
128	      else if (oursContent === targetContent) outcome = "skip";
129	      else outcome = "merge";
130	    }
131	
132	    entries.push({ path, upstream, oursModified: inTheWay, outcome });
133	  }
134	
135	  const by = (outcome: UpdateOutcome) => entries.filter((e) => e.outcome === outcome).map((e) => e.path);
136	  return {
137	    base,
138	    target,
139	    entries,
140	    take: by("take"),
141	    add: by("add"),
142	    delete: by("delete"),
143	    merge: by("merge"),
144	    kept: entries.filter((e) => e.outcome === "keep"),
145	  };
146	}
