34	/** What applying a plan did, as the pull request and the notices render it. */
35	export interface ApplyResult {
36	  /** Paths that took the target's content (plan: take), written. */
37	  readonly taken: readonly string[];
38	  /** Plan: add — paths created. */
39	  readonly added: readonly string[];
40	  /** Plan: delete — paths removed. */
41	  readonly removed: readonly string[];
42	  /** Plan: merge — paths whose three-way merge resolved with no conflict. */
43	  readonly merged: readonly string[];
44	  /** Plan: merge — paths whose merge collided, now carrying conflict markers. */
45	  readonly conflicts: readonly string[];
46	}
47	
48	/** Every path refuses together: no `why` means the tree holds the whole plan. */
49	export type Applied = { result: ApplyResult } | { why: string };
