51	/**
52	 * Apply `plan` to the tree at `treeRoot`.
53	 *
54	 * `base` and `target` are the two releases' contents; `ours` is what the tree holds
55	 * at the paths the plan cares about (the same map `planUpdate` read). Writes are
56	 * whole-file — the release ships files as they are, so an update is byte-for-byte
57	 * what the release carries, not a patch sequence.
58	 */
59	export function applyPlan(
60	  treeRoot: string,
61	  plan: UpdatePlan,
62	  base: ReadonlyMap<string, string>,
63	  target: ReadonlyMap<string, string>,
64	  ours: ReadonlyMap<string, string>,
65	): Applied {
66	  const root = resolve(treeRoot);
67	  /** Where `path` lands inside the tree, or null when it would escape it. */
68	  const inside = (path: string): string | null => {
69	    const destination = resolve(join(root, path));
70	    if (destination !== root && !destination.startsWith(root + sep)) return null;
71	    return destination;
72	  };
73	
74	  // Every path the plan names is validated before anything runs: an escaping
75	  // path is a refusal that costs nothing, and refusing late -- after the merges
76	  // have run, at the write loop -- would leave a tree holding half a plan. The
77	  // paths come from the release's own manifest and archive, so this is the
78	  // boundary a malformed release is caught at.
79	  for (const path of [...plan.take, ...plan.add, ...plan.delete, ...plan.merge]) {
80	    if (inside(path) === null) return { why: `\`${path}\` resolves outside the tree` };
81	  }
82	
83	  // Decide everything: content per path to write, paths to delete. The tree is
84	  // untouched until every decision has succeeded.
85	  const writes = new Map<string, string>();
86	  const deletes = new Set<string>();
87	  const taken: string[] = [];
88	  const added: string[] = [];
89	  const removed: string[] = [];
90	  const merged: string[] = [];
91	  const conflicts: string[] = [];
92	
93	  for (const path of plan.take) {
94	    const content = target.get(path);
95	    if (content === undefined) {
96	      return { why: `the target release does not carry \`${path}\`, which the plan says to take` };
97	    }
98	    writes.set(path, content);
99	    taken.push(path);
100	  }
101	  for (const path of plan.add) {
102	    const content = target.get(path);
103	    if (content === undefined) {
104	      return { why: `the target release does not carry \`${path}\`, which the plan says to add` };
105	    }
106	    // A path upstream adds where the plan says nothing is in the way is a file the
107	    // tree should not already hold; refuse to clobber one that appeared anyway.
108	    // Containment was validated up front for every path in the plan, so the null
109	    // branch is unreachable -- kept for the type, not for the runtime.
110	    const destination = inside(path);
111	    if (destination === null) return { why: `\`${path}\` resolves outside the tree` };
112	    if (existsSync(destination)) {
113	      return { why: `\`${path}\` exists in the tree but the plan did not expect it` };
114	    }
115	    writes.set(path, content);
116	    added.push(path);
117	  }
118	  for (const path of plan.delete) {
119	    deletes.add(path);
120	    removed.push(path);
121	  }
122	
123	  const scratch = (() => {
124	    try {
125	      return mkdtempSync(join(tmpdir(), "atomaton-merge-"));
126	    } catch (error) {
127	      return null;
128	    }
129	  })();
130	  if (scratch === null) {
131	    return { why: `could not make a scratch directory for the merges` };
132	  }
133	  try {
134	    for (const path of plan.merge) {
135	      const baseContent = base.get(path);
136	      const oursContent = ours.get(path);
137	      const targetContent = target.get(path);
138	      if (baseContent === undefined || oursContent === undefined || targetContent === undefined) {
139	        return { why: `\`${path}\` is marked for a merge this run cannot read all three sides of` };
140	      }
141	      const outcome = mergeFile(scratch, basename(path) || path, baseContent, oursContent, targetContent);
142	      if ("why" in outcome) return { why: outcome.why };
143	      writes.set(path, outcome.content);
144	      (outcome.conflicts > 0 ? conflicts : merged).push(path);
145	    }
146	  } finally {
147	    try {
148	      rmSync(scratch, { recursive: true, force: true, maxRetries: 5, retryDelay: 50 });
149	    } catch {
150	      // The OS owns a temp directory it will not let go of.
151	    }
152	  }
153	
154	  // Then act. Writes first (parents included), deletions after — order only
155	  // matters where a release moves a directory's contents around, which no two
156	  // releases of this tree have done. Containment was validated for every path
157	  // up front, so this loop has no refusals left to make -- EXCEPT one shape the
